-- Additional seasonal products for storefront categories.
ON CONFLICT (id) DO UPDATE SET
  name_en = EXCLUDED.name_en, name_bn = EXCLUDED.name_bn, category = EXCLUDED.category,
  audience = EXCLUDED.audience, description_en = EXCLUDED.description_en, description_bn = EXCLUDED.description_bn,
  fabric = EXCLUDED.fabric, badge = EXCLUDED.badge, image_url = EXCLUDED.image_url, is_published = TRUE;

ON CONFLICT (id) DO UPDATE SET
  product_id = EXCLUDED.product_id, sku = EXCLUDED.sku, size = EXCLUDED.size,
  color = EXCLUDED.color, color_code = EXCLUDED.color_code, price_bdt = EXCLUDED.price_bdt,
  stock = EXCLUDED.stock, is_available = EXCLUDED.is_available;
