INSERT INTO public.products (id, name_en, name_bn, category, audience, description_en, description_bn, fabric, origin, badge, image_url)
VALUES
  ('prod-07', 'Rosewood Zardozi Evening Kaftan', 'রোজউড জারদৌসি ইভনিং কাফতান', 'Kaftans', 'women', 'A flowing velvet kaftan finished with fine zardozi around the neckline and cuffs.', 'নেকলাইন ও হাতায় সূক্ষ্ম জারদৌসি কাজের রোজউড ভেলভেট কাফতান, সন্ধ্যার উৎসবের জন্য উপযোগী।', 'Velvet with hand-finished zardozi', 'Dhaka, Bangladesh', 'New Arrival', 'https://images.unsplash.com/photo-1566174053879-31528523f8ae?auto=format&fit=crop&w=900&q=85'),
  ('prod-08', 'Ivory Pearl Embroidered Kaftan', 'আইভরি পার্ল এমব্রয়ডার্ড কাফতান', 'Kaftans', 'women', 'Soft ivory occasionwear with pearl-toned threadwork and a relaxed, graceful drape.', 'মুক্তার রঙের সুতোয় নকশা করা কোমল আইভরি কাফতান, বিয়ে ও পারিবারিক অনুষ্ঠানের জন্য।', 'Silk-touch velvet and pearl thread', 'Dhaka, Bangladesh', 'New Arrival', 'https://images.unsplash.com/photo-1595777457583-95e059d581b8?auto=format&fit=crop&w=900&q=85'),
  ('prod-09', 'Midnight Jacquard Festive Panjabi', 'মিডনাইট জ্যাকার্ড ফেস্টিভ পাঞ্জাবি', 'Panjabis', 'men', 'A tailored panjabi in deep navy jacquard, finished with a neat band collar.', 'গভীর নেভি জ্যাকার্ড কাপড়ে নিখুঁত ব্যান্ড কলারের উৎসবের পাঞ্জাবি।', 'Cotton jacquard', 'Dhaka, Bangladesh', 'New Arrival', 'https://images.unsplash.com/photo-1597983073493-88cd35cf93b0?auto=format&fit=crop&w=900&q=85'),
  ('prod-10', 'Sandstone Handloom Cotton Panjabi', 'স্যান্ডস্টোন হ্যান্ডলুম কটন পাঞ্জাবি', 'Panjabis', 'men', 'A breathable handloom cotton panjabi with understated tonal stitching.', 'আরামদায়ক হ্যান্ডলুম কটনে তৈরি স্যান্ডস্টোন পাঞ্জাবি, সূক্ষ্ম টোনাল সেলাইয়ের কাজসহ।', 'Handloom cotton', 'Dhaka, Bangladesh', 'New Arrival', 'https://images.unsplash.com/photo-1602810318383-e386cc2a3ccf?auto=format&fit=crop&w=900&q=85'),
  ('prod-11', 'Ruby Garden Silk Saree', 'রুবি গার্ডেন সিল্ক শাড়ি', 'Sarees', 'women', 'A rich ruby silk saree with a delicate woven border for celebrations and receptions.', 'উৎসব ও রিসেপশনের জন্য সূক্ষ্ম বুনন পাড়ের সমৃদ্ধ রুবি সিল্ক শাড়ি।', 'Silk blend with woven border', 'Dhaka, Bangladesh', 'New Arrival', 'https://images.unsplash.com/photo-1610030469983-98e550d6193c?auto=format&fit=crop&w=900&q=85'),
  ('prod-12', 'Champagne Tissue Organza Saree', 'শ্যাম্পেন টিস্যু অর্গানজা শাড়ি', 'Sarees', 'women', 'Lightweight champagne organza with a fine metallic edge and matching blouse piece.', 'হালকা শ্যাম্পেন অর্গানজা শাড়ি, সূক্ষ্ম মেটালিক পাড় ও ম্যাচিং ব্লাউজ পিসসহ।', 'Tissue organza with metallic trim', 'Dhaka, Bangladesh', 'New Arrival', 'https://images.unsplash.com/photo-1583391733956-6c78276477e2?auto=format&fit=crop&w=900&q=85'),
  ('prod-13', 'Little Heirloom Cotton Panjabi Set', 'লিটল হেয়ারলুম কটন পাঞ্জাবি সেট', 'Kids Wear', 'kids', 'A comfortable cotton panjabi set for little ones, with neat contrast piping.', 'ছোটদের জন্য আরামদায়ক কটন পাঞ্জাবি সেট, সুন্দর কনট্রাস্ট পাইপিং ফিনিশিংসহ।', 'Soft cotton with contrast piping', 'Dhaka, Bangladesh', 'New Arrival', 'https://images.unsplash.com/photo-1503919545889-aef636e10ad4?auto=format&fit=crop&w=900&q=85'),
  ('prod-14', 'Emerald Velvet Koti Festive Set', 'এমারেল্ড ভেলভেট কোটি ফেস্টিভ সেট', 'Kids Wear', 'kids', 'A festive children’s outfit pairing an embroidered velvet koti with a soft cotton panjabi.', 'নরম সুতি পাঞ্জাবির সাথে কারুকাজ করা পান্না সবুজ ভেলভেট কোটির উৎসবের সেট।', 'Cotton panjabi with velvet koti', 'Dhaka, Bangladesh', 'New Arrival', 'https://images.unsplash.com/photo-1519238263530-99bdd11df2ea?auto=format&fit=crop&w=900&q=85'),
  ('prod-15', 'Camel Border Cashmere Winter Shawl', 'ক্যামেল বর্ডার ক্যাশমিয়ার শীতের শাল', 'Shawls', 'unisex', 'A warm, lightweight shawl with a soft hand and a contrasting woven border.', 'উষ্ণ ও হালকা কাশ্মীরি শীতের শাল, মসৃণ টেক্সচার ও বুনন পাড়সহ।', 'Cashmere blend with woven border', 'Dhaka, Bangladesh', 'New Arrival', 'https://images.unsplash.com/photo-1520903920243-00d872a2d1c9?auto=format&fit=crop&w=900&q=85'),
  ('prod-16', 'Mulberry Velvet Reversible Shawl', 'মালবেরি ভেলভেট রিভার্সিবল শাল', 'Shawls', 'unisex', 'A reversible winter wrap with a smooth velvet face and a soft, warm reverse.', 'একপাশে মসৃণ মালবেরি ভেলভেট ও অন্যপাশে উষ্ণ ক্যাশমিয়ার সমৃদ্ধ রিভার্সিবল শাল।', 'Mulberry velvet and cashmere blend', 'Dhaka, Bangladesh', 'New Arrival', 'https://images.unsplash.com/photo-1601924994987-69e26d50dc26?auto=format&fit=crop&w=900&q=85')
